mapper.select:
SELECT m.magazine_no, m.magazine_title, m.magazine_content, m.magazine_reg_date, m.magazine_view_cnt, f.file_no, f.file_name, f.file_path, f.file_system_name FROM magazine m LEFT JOIN files f ON m.magazine_no = f.magazine_no
WHERE ${key} LIKE concat('%',#{word},'%')
ORDER BY ${orderBy} ${orderByDir}

mapper.update:
UPDATE magazine
SET magazine_view_cnt = magazine_view_cnt + 1
WHERE magazine_no = #{no}

UPDATE magazine
SET magazine_title = #{magazineTitle}, magazine_content = #{magazineContent}
WHERE magazine_no = #{magazineNo};
